import importlib.metadata
import logging
import sys

if sys.version_info[:2] >= (3, 10):
    entry_points = importlib.metadata.entry_points
else:
    def entry_points(group):
        return importlib.metadata.entry_points().get(group, [])


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class ExecutorFactoryRegistry(object):
    _instance = None

    def __init__(self, **kwargs):
        super(ExecutorFactoryRegistry, self).__init__(**kwargs)
        self._map = {}
        for entry_point in entry_points(group="ExecutorFactory"):
            logger.debug(f"entry point name: {entry_point.name!r}")
            self._map[entry_point.name] = entry_point.load()
        logger.debug("factory registry: %r", self._map)

    def __getitem__(self, executor_type):
        return self._map[executor_type]

    @classmethod
    def get_instance(cls):
        if cls._instance is None:
            cls._instance = ExecutorFactoryRegistry()
        return cls._instance
